    "key": "sample:collection:01_kintsugi",
    "name": "金継ぎ陶片",
    "kind": "image",
    "source": "// 金継ぎ陶片｜画像 JavaScript の関数本体。立体化なし専用。\n// 画像の面が薄い陶片へ変わり、開いた細いひびを金がゆっくり埋める。\nconst {THREE, createImagePlane, size} = api;\nconst CLAMP = (x, a, b) => Math.max(a, Math.min(b, x));\nconst DENSITY = 6.8;     // 高さ方向の陶片数：3〜12\nconst CRACK_WIDTH = 0.033; // セルに対するひび幅：0.008〜0.07\nconst SEPARATION = 0.12; // 陶片のずれ：0〜0.25（セル単位）\nconst GLAZE = 0.24;      // 白い釉薬の強さ：0〜0.6\nconst GOLD = 0.92;       // 金の濃さ：0〜1\nconst SHIMMER = 0.65;    // 金の上を移動する光：0〜1\nconst plane = createImagePlane();\nconst material = plane.material;\nconst finite = (x, fallback) => Number.isFinite(x) ? x : fallback;\nconst aspect = Math.max(0.01, finite(size.width / size.height, 1));\nObject.assign(material.uniforms, {\n  ktAspect: {value: aspect}, ktDensity: {value: CLAMP(DENSITY, 3, 12)},\n  ktWidth: {value: CLAMP(CRACK_WIDTH, 0.008, 0.07)},\n  ktSeparation: {value: CLAMP(SEPARATION, 0, 0.25)},\n  ktGlaze: {value: CLAMP(GLAZE, 0, 0.6)}, ktGold: {value: CLAMP(GOLD, 0, 1)},\n  ktShimmer: {value: CLAMP(SHIMMER, 0, 1)},\n  ktActive: {value: 0}, ktRepair: {value: 0}, ktTime: {value: 0}\n});\n// a / b / mixImage の参照を残し、本体による画像切替を維持する。\nmaterial.transparent = true;\nmaterial.depthWrite = false;\nmaterial.fragmentShader = `\nuniform sampler2D a,b;\nuniform float mixImage;\nuniform float ktAspect,ktDensity,ktWidth,ktSeparation,ktGlaze,ktGold;\nuniform float ktShimmer,ktActive,ktRepair,ktTime;\nvarying vec2 vUv;\nvec2 ktHash(vec2 p){\n  return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453);\n}\nvec4 ktSample(vec2 uv){\n  return mix(texture2D(a,uv),texture2D(b,uv),mixImage);\n}\nvoid main(){\n  vec4 original=ktSample(vUv);\n  vec2 metric=vec2(ktAspect,1.0)*ktDensity;\n  vec2 q=vUv*metric, cell=floor(q);\n  float nearest=1000.0;\n  vec2 nearestPoint=vec2(0.0),id=vec2(0.0);\n  for(int yy=-1;yy<=1;yy++){\n    for(int xx=-1;xx<=1;xx++){\n      vec2 candidate=cell+vec2(float(xx),float(yy));\n      vec2 point=candidate+0.16+0.68*ktHash(candidate);\n      float d=dot(point-q,point-q);\n      if(d<nearest){nearest=d;nearestPoint=point;id=candidate;}\n    }\n  }\n  // 二つの種点の二等分線までの距離。幅の揃った陶器のひびになる。\n  float edge=1000.0;\n  for(int yy=-1;yy<=1;yy++){\n    for(int xx=-1;xx<=1;xx++){\n      vec2 candidate=cell+vec2(float(xx),float(yy));\n      vec2 point=candidate+0.16+0.68*ktHash(candidate);\n      vec2 delta=point-nearestPoint;\n      float length2=dot(delta,delta);\n      if(length2>0.0001){\n        float d=dot((point+nearestPoint)*0.5-q,delta*inversesqrt(length2));\n        edge=min(edge,d);\n      }\n    }\n  }\n  vec2 seed=ktHash(id+vec2(13.2,8.7));\n  float activity=ktActive;\n  // 修復が進むと陶片のずれが縮まり、金線だけが残る。\n  float spread=activity*ktSeparation*(1.0-0.80*ktRepair);\n  vec2 shift=(seed-0.5)*spread;\n  vec2 uv=clamp(vUv-shift/metric,vec2(0.001),vec2(0.999));\n  vec4 tex=ktSample(uv);\n  vec3 sampledRGB=mix(original.rgb,tex.rgb,clamp(tex.a,0.0,1.0));\n  float luma=dot(sampledRGB,vec3(0.2126,0.7152,0.0722));\n  vec3 glazeColor=mix(sampledRGB,vec3(luma)*0.73+vec3(0.25,0.23,0.20),ktGlaze*activity);\n  float ceramicLight=(seed.x-0.5)*0.16*activity;\n  vec3 ceramic=max(vec3(0.0),glazeColor*(1.0+ceramicLight));\n  float width=ktWidth*(0.24+0.76*activity);\n  float seam=(1.0-smoothstep(width*0.55,width*1.28,edge))*activity;\n  float bevel=(1.0-smoothstep(width*1.4,width*4.4,edge))*activity;\n  ceramic*=1.0-0.23*bevel;\n  // 左上から下へ金が流れる。細胞ごとに少し遅れ、直線ワイプにしない。\n  float arrival=0.16+0.36*vUv.x+0.20*(1.0-vUv.y)+0.18*seed.y;\n  float filled=smoothstep(arrival-0.15,arrival+0.12,ktRepair);\n  float lightBand=pow(max(0.0,0.5+0.5*sin(q.x*0.47+q.y*0.65-ktTime*1.6)),12.0);\n  float glint=ktShimmer*(0.15+0.85*lightBand);\n  vec3 goldColor=mix(vec3(0.30,0.115,0.023),vec3(0.92,0.61,0.16),0.43+0.57*seed.x);\n  goldColor+=vec3(0.30,0.25,0.11)*glint;\n  vec3 grout=mix(vec3(0.014,0.010,0.008),goldColor,filled*ktGold);\n  vec3 rgb=mix(ceramic,grout,seam);\n  // 元画像の透明部分へ金や釉薬を描かない。全透明画像は全透明のまま。\n  float alpha=original.a;\n  gl_FragColor=mix(original,vec4(rgb,alpha),activity);\n  #include <colorspace_fragment>\n}`;\nmaterial.needsUpdate = true;\nconst smooth = (a,b,x) => {\n  const q = CLAMP((x-a)/(b-a),0,1);\n  return q*q*(3-2*q);\n};\nreturn {\n  physicsTime:()=>0,\n  update(frame){\n    const duration=Math.max(0.0001,finite(frame.duration,6));\n    const t=CLAMP(finite(frame.clipTime,0),0,duration);\n    const p=CLAMP(finite(frame.progress,t/duration),0,1);\n    const strength=CLAMP(finite(frame.amount,0)/0.8,0,1);\n    material.uniforms.ktActive.value=smooth(0.025,0.18,p)*(1-smooth(0.80,0.985,p))*strength;\n    material.uniforms.ktRepair.value=smooth(0.20,0.67,p);\n    material.uniforms.ktTime.value=t;\n  }\n};\n",
