    "source": "// 弾力活字 — pressure, release, and a soft rebound, without changing the ink.\n// Paste this entire function body into UNFOLD TEXT's code editor.\nconst { THREE, gsap, scene, createText } = api;\nconst source = String(api.text == null ? \"\" : api.text);\nconst finite = (n, fallback) => Number.isFinite(n) ? n : fallback;\nconst W = Math.max(1, finite(api.width, 1280));\nconst H = Math.max(1, finite(api.height, 720));\nconst em = Math.max(1, finite(api.fontSize, 96));\nconst life = Math.max(0.001, finite(api.duration, 6));\nconst tempo = Math.min(180, Math.max(60, finite(api.bpm, 120)));\nconst pulseHz = tempo / 120 * 0.86;\nconst intro = Math.min(0.46, life * 0.26);\nconst outro = Math.min(0.42, life * 0.24);\nconst stagger = Math.min(0.15, life * 0.09);\nconst smooth = n => { const x = Math.max(0, Math.min(1, n)); return x * x * (3 - 2 * x); };\nconst root = new THREE.Group();\nscene.add(root);\nconst clock = { t: 0 };\nconst timeline = gsap.timeline({ paused: true });\ntimeline.to(clock, { t: life, duration: life, ease: \"none\" }, 0);\nconst segments = [];\nif (typeof Intl !== \"undefined\" && Intl.Segmenter) {\n  const iterator = new Intl.Segmenter(\"ja\", { granularity: \"grapheme\" }).segment(source);\n  for (const item of iterator) segments.push({ value: item.segment, start: item.index });\n} else {\n  let offset = 0;\n  for (const value of Array.from(source)) {\n    const previous = segments[segments.length - 1];\n    if (previous && (/^[\\p{Mark}\\uFE0E\\uFE0F\\u200D]$/u.test(value) || previous.value.endsWith(\"\\u200D\"))) previous.value += value;\n    else segments.push({ value, start: offset });\n    offset += value.length;\n  }\n}\nconst lines = [[]];\nlet length = 0;\nfor (const part of segments) {\n  if (/\\r|\\n/.test(part.value)) {\n    // Intl treats CRLF as one grapheme; the fallback path joins the pair here.\n    if (part.value === \"\\n\" && source[part.start - 1] === \"\\r\") continue;\n    lines.push([]);\n  } else {\n    lines[lines.length - 1].push(part);\n    length++;\n  }\n}\nconst unitWidth = value => {\n  let n = 0;\n  for (const ch of Array.from(value)) {\n    if (/\\p{Mark}|\\uFE0F|\\u200D/u.test(ch)) continue;\n    n += /\\s/.test(ch) ? 0.32 : ch.codePointAt(0) < 256 ? 0.59 : 1;\n  }\n  return Math.max(0.1, n);\n};\nlet units = 0;\nfor (const line of lines) for (const p of line) units += unitWidth(p.value);\nconst safeW = W * 0.78;\nconst safeH = H * 0.65;\nconst wrapWidth = em * Math.max(6, Math.min(28, Math.sqrt(Math.max(1, units) * safeW / safeH * 1.38)));\nconst chunkSize = Math.max(1, Math.ceil(length / 112));\nconst descriptors = [];\nfor (let line = 0; line < lines.length; line++) {\n  const parts = lines[line];\n  for (let i = 0; i < parts.length; i += chunkSize) {\n    const slice = parts.slice(i, i + chunkSize);\n    descriptors.push({ value: slice.map(p => p.value).join(\"\"), start: slice[0].start, line });\n  }\n}\n// Very many intentional line breaks use one multiline mesh rather than dropping text.\nconst bulk = descriptors.length > 160 || lines.length > 48;\nif (bulk) {\n  descriptors.length = 0;\n  if (source.trim()) descriptors.push({ value: source, start: 0, line: 0 });\n}\nconst letters = descriptors.map((part, i) => {\n  const options = { textStart: part.start, fontSize: em, anchorX: \"center\", anchorY: \"bottom\", lineHeight: 1.16 };\n  if (bulk) Object.assign(options, { maxWidth: wrapWidth, textAlign: \"center\", overflowWrap: \"break-word\" });\n  const mesh = createText(part.value, options);\n  root.add(mesh);\n  mesh.fillOpacity = 0;\n  mesh.outlineOpacity = 0;\n  const estimatedHeight = em * 1.16 * (bulk ? lines.length : 1);\n  const estimatedWidth = Math.min(bulk ? wrapWidth : Infinity, unitWidth(part.value) * em);\n  return { mesh, line: part.line, order: descriptors.length > 1 ? i / (descriptors.length - 1) : 0.5,\n    phase: i * 0.38 + part.line * 0.27, width: estimatedWidth, height: estimatedHeight,\n    centerX: 0, bottom: 0, x: 0, y: 0, metrics: null };\n});\nlet fit = 1;\nlet disposed = false;\nfunction layout() {\n  const rows = [];\n  const gap = em * 0.12;\n  let row = { items: [], width: 0 };\n  let currentLine = 0;\n  let maxHeight = em * 1.16;\n  for (const letter of letters) {\n    const info = letter.mesh.textRenderInfo;\n    const b = info && info.blockBounds;\n    if (b && b.length === 4 && b.every(Number.isFinite)) {\n      letter.width = Math.max(0, b[2] - b[0]);\n      letter.height = Math.max(0, b[3] - b[1]);\n      letter.centerX = (b[0] + b[2]) * 0.5;\n      letter.bottom = b[1];\n      letter.metrics = info;\n    }\n    maxHeight = Math.max(maxHeight, letter.height);\n    while (letter.line > currentLine) {\n      rows.push(row);\n      row = { items: [], width: 0 };\n      currentLine++;\n    }\n    if (row.items.length && row.width + gap + letter.width > wrapWidth) {\n      rows.push(row);\n      row = { items: [], width: 0 };\n    }\n    if (row.items.length) row.width += gap;\n    letter.x = row.width + letter.width * 0.5;\n    row.items.push(letter);\n    row.width += letter.width;\n  }\n  if (row.items.length) rows.push(row);\n  if (!rows.length) return;\n  const step = maxHeight * 1.36;\n  const totalHeight = (rows.length - 1) * step + maxHeight * 1.36;\n  let maximumWidth = 1;\n  for (let i = 0; i < rows.length; i++) {\n    maximumWidth = Math.max(maximumWidth, rows[i].width);\n    for (const letter of rows[i].items) {\n      letter.x -= rows[i].width * 0.5;\n      letter.y = (rows.length - 1 - i) * step - totalHeight * 0.5;\n    }\n  }\n  fit = Math.min(1, safeW / (maximumWidth * 1.1), safeH / totalHeight);\n  root.scale.setScalar(fit);\n}\nlayout();\nfunction update(time) {\n  if (disposed) return;\n  const t = Math.max(0, Math.min(life, finite(time, 0)));\n  // The runtime's initial Troika sync is async. Consume measured font bounds on arrival.\n  let changed = false;\n  for (const letter of letters) if (letter.mesh.textRenderInfo && letter.metrics !== letter.mesh.textRenderInfo) changed = true;\n  if (changed) layout();\n  for (const letter of letters) {\n    const enter = smooth((t - stagger * letter.order) / intro);\n    const leave = 1 - smooth((t - (life - outro - stagger * (1 - letter.order))) / outro);\n    const alpha = enter * leave;\n    const angle = 2 * Math.PI * pulseHz * t - letter.phase;\n    const pressure = Math.pow(0.5 + 0.5 * Math.cos(angle), 6);\n    const rebound = Math.pow(0.5 + 0.5 * Math.cos(angle - 1.8), 8);\n    const edge = (1 - enter) * 0.14 + (1 - leave) * 0.11;\n    const sx = 1 - 0.135 * pressure + 0.046 * rebound - edge;\n    const sy = 1 + 0.18 * pressure - 0.06 * rebound + edge * 0.68;\n    const mesh = letter.mesh;\n    mesh.scale.set(sx, sy, 1);\n    mesh.position.set(letter.x - letter.centerX * sx, letter.y - letter.bottom * sy, 0);\n    mesh.rotation.set(0, 0, 0);\n    mesh.fillOpacity = alpha;\n    mesh.outlineOpacity = 0;\n    mesh.visible = alpha > 0.00001;\n  }\n}\nupdate(0);\nfunction dispose() {\n  if (disposed) return;\n  disposed = true;\n  timeline.kill();\n  for (const letter of letters) {\n    root.remove(letter.mesh);\n    letter.mesh.dispose();\n  }\n  scene.remove(root);\n}\nreturn { timeline, update, dispose };\n",
