    "source": "// SUMI / 墨の余韻 — an original, seek-safe UNFOLD motion.\n// A dry-brush ribbon carries the chosen type and color; flecks breathe around it.\nconst {THREE,scene,createText,text,width,height,fontSize,color,accent,duration,random}=api;\nconst D=Math.max(.001,duration), S=Math.min(width,height);\nconst clamp=x=>Math.max(0,Math.min(1,x));\nconst smooth=x=>{x=clamp(x);return x*x*(3-2*x)};\nconst ease=x=>1-Math.pow(1-clamp(x),3);\nconst root=new THREE.Group();scene.add(root);\nconst geometries=[],materials=[];\nconst keepG=g=>(geometries.push(g),g),keepM=m=>(materials.push(m),m);\nconst chosen=new THREE.Color(color),highlight=new THREE.Color(accent);\nconst lightType=chosen.r*.2126+chosen.g*.7152+chosen.b*.0722>.28;\nconst ink=new THREE.Color(lightType?'#102c3f':'#f3e8d1');\nconst wash=new THREE.Color(lightType?'#31576a':'#ddc9a4');\nconst gold=new THREE.Color('#d0b578');\nconst label=createText(text,{fontSize,overflowWrap:'break-word',maxWidth:width*.75,textAlign:'center',lineHeight:1.22,color,outlineWidth:'1.2%',outlineColor:lightType?'#102331':'#fbf2dd',outlineOpacity:0,fillOpacity:0,textStart:0});\nroot.add(label);label.position.z=4;label.renderOrder=5;\nconst textMaterials=Array.isArray(label.material)?label.material:[label.material];\nfor(const material of textMaterials){material.depthTest=false;material.depthWrite=false;}\nconst plane=keepG(new THREE.PlaneGeometry(1,1));\nconst vertex=`varying vec2 vUv;\nvoid main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`;\nconst fragment=`precision highp float;\nvarying vec2 vUv;uniform vec3 uColor;uniform float uAlpha,uReveal,uErase,uSeed;\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7))+uSeed)*43758.5453);}\nfloat noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.)),f.x),f.y);}\nvoid main(){\n vec2 p=vUv;float x=p.x,y=p.y-.5;\n float taper=pow(max(0.,sin(x*3.14159265)),.25);\n float edge=.365*taper+.022*sin(x*51.+uSeed)+.016*sin(x*107.+uSeed*2.);\n float outer=1.-smoothstep(edge-.025,edge+.018,abs(y+.018*sin(x*13.+uSeed)));\n float fiber=noise(vec2(x*9.,p.y*170.));\n float dry=smoothstep(.08,.52,fiber)*.30+.70;\n float pores=smoothstep(.12,.32,noise(p*vec2(220.,55.)));\n float ribs=1.-.18*smoothstep(.72,.87,noise(vec2(x*8.,p.y*280.)));\n float head=1.-smoothstep(uReveal-.03,uReveal+.018,x);\n float tail=smoothstep(uErase-.035,uErase+.018,x);\n float a=outer*dry*pores*ribs*head*tail*uAlpha;\n if(a<.002)discard;gl_FragColor=vec4(uColor,a);\n #include <colorspace_fragment>\n}`;\nconst strokes=[];\nfor(let i=0;i<3;i++){\n const m=keepM(new THREE.ShaderMaterial({transparent:true,depthWrite:false,depthTest:false,uniforms:{uColor:{value:i===0?wash:i===1?ink:highlight},uAlpha:{value:0},uReveal:{value:0},uErase:{value:0},uSeed:{value:7.1+i*12.3}},vertexShader:vertex,fragmentShader:fragment}));\n const mesh=new THREE.Mesh(plane,m);mesh.renderOrder=i;mesh.position.z=-4+i;root.add(mesh);strokes.push({mesh,m});\n}\n// A broken ensō is deliberately off-center, leaving the text calm and level.\nconst circles=[];\nfor(let j=0;j<3;j++){\n const pts=[];for(let i=0;i<101;i++){const a=(-.1+i/100*1.76)*Math.PI;const r=1+.019*Math.sin(a*7+j)+.012*Math.sin(a*19);pts.push(new THREE.Vector3(Math.cos(a)*r,Math.sin(a)*r,0));}\n const g=keepG(new THREE.BufferGeometry().setFromPoints(pts));\n const m=keepM(new THREE.LineBasicMaterial({color:j===0?gold:highlight,transparent:true,opacity:0,depthTest:false,depthWrite:false}));\n const line=new THREE.Line(g,m);line.renderOrder=-2;line.position.z=-10;root.add(line);circles.push({line,g,m,j});\n}\nconst dot=keepG(new THREE.CircleGeometry(1,7)),flecks=[];\nfor(let i=0;i<58;i++){\n const a=random()*Math.PI*2,r=.5+random()*.48;\n const m=keepM(new THREE.MeshBasicMaterial({color:i%5===0?highlight:i%3===0?gold:wash,transparent:true,opacity:0,depthWrite:false,depthTest:false}));\n const mesh=new THREE.Mesh(dot,m);mesh.renderOrder=i%4===0?6:2;root.add(mesh);\n flecks.push({mesh,m,a,r,phase:random()*6.283,drift:(random()-.5)*.16,size:(.0018+random()*.0045)*S,delay:random()*.15,ratio:.35+random()*.8,rot:random()*6.283});\n}\nconst lineG=keepG(new THREE.PlaneGeometry(1,1));\nconst ruleM=keepM(new THREE.MeshBasicMaterial({color:gold,transparent:true,opacity:0,depthTest:false,depthWrite:false}));\nconst rule=new THREE.Mesh(lineG,ruleM);rule.renderOrder=3;root.add(rule);\nreturn {\n update(t){\n  const p=clamp(t/D),enter=ease(p/.27),exit=smooth((p-.79)/.21);\n  const fade=smooth(p/.12)*(1-smooth((p-.80)/.20));\n  const bounds=label.textRenderInfo?.blockBounds;\n  const bw=bounds?Math.max(1,bounds[2]-bounds[0]):Math.max(fontSize,Array.from(text).length*fontSize*.65);\n  const bh=bounds?Math.max(1,bounds[3]-bounds[1]):fontSize*1.22;\n  const fit=Math.min(1,width*.75/bw,height*.45/bh);\n  const textH=bh*fit;\n  const brushH=Math.min(height*.64,Math.max(textH*1.48,S*.23));\n  label.scale.setScalar(fit*(.975+.025*ease((p-.12)/.22)));\n  label.position.set((1-ease((p-.10)/.22))*width*.025+exit*width*.02,(1-ease((p-.10)/.24))*-S*.023+exit*S*.025,4);\n  label.rotation.z=0;\n  const textFade=smooth((p-.12)/.17)*(1-smooth((p-.79)/.17));\n  label.fillOpacity=textFade;label.outlineOpacity=textFade*.65;\n  for(let i=0;i<strokes.length;i++){\n   const {mesh,m}=strokes[i];\n   mesh.scale.set(width*(i===2?.82:.96),brushH*(i===0?1.16:i===1?1:.09),1);\n   mesh.position.set((i-1)*width*.012,i===2?-brushH*.43:(i===0?brushH*.04:0),-4+i);\n   mesh.rotation.z=i===0?-.026:i===1?-.018:-.04;\n   m.uniforms.uAlpha.value=fade*(i===0?.35:i===1?.96:.50);\n   m.uniforms.uReveal.value=1.06*ease((p-i*.025)/.27);\n   m.uniforms.uErase.value=1.06*exit-.04;\n  }\n  circles.forEach(({line,g,m,j})=>{\n   const rr=Math.min(width*.23,height*.34);\n   line.position.set(-width*.28,height*.045,-10-j);\n   line.scale.set(rr*(1+j*.034),rr*(.95+j*.028),1);\n   line.rotation.z=-.18+j*.03+(1-enter)*-.32;\n   g.setDrawRange(0,Math.floor(101*ease((p-.015)/.32)));\n   m.opacity=fade*(j===0?.36:.14);\n  });\n  for(const f of flecks){\n   const arrival=ease((p-f.delay)/.27),a=f.a+(1-arrival)*-.14+p*f.drift;\n   const rx=width*.49*f.r,ry=Math.max(brushH*.71,S*.26)*f.r;\n   f.mesh.position.set(Math.cos(a)*rx+(1-arrival)*width*.06,Math.sin(a)*ry+Math.sin(p*4+f.phase)*S*.006,1);\n   f.mesh.rotation.z=f.rot+p*f.drift;\n   const sz=f.size*(.5+.5*arrival)*(1+.1*Math.sin(p*8+f.phase));\n   f.mesh.scale.set(sz,sz*f.ratio,1);\n   const away=Math.abs(Math.sin(a));\n   f.m.opacity=fade*smooth((p-f.delay)/.10)*(.18+.56*away)*(1-.35*exit);\n  }\n  const ruleReveal=ease((p-.20)/.23);\n  rule.scale.set(width*.16*ruleReveal,Math.max(.65,S*.0016),1);\n  rule.position.set(width*.25,-brushH*.55,3);\n  rule.rotation.z=-.025;ruleM.opacity=fade*.60;\n  root.visible=p>0&&p<1;\n },\n dispose(){scene.remove(root);for(const g of geometries)g.dispose();for(const m of materials)m.dispose();}\n};\n",
