    "source": "// HANA / 花の軌道 — an original, seek-safe UNFOLD motion.\n// Folded petals drift along open orbits around the chosen type, never over it.\nconst {THREE,scene,createText,text,width,height,fontSize,color,accent,duration,random}=api;\nconst D=Math.max(.001,duration),S=Math.min(width,height);\nconst clamp=x=>Math.max(0,Math.min(1,x));\nconst smooth=x=>{x=clamp(x);return x*x*(3-2*x)};\nconst ease=x=>1-Math.pow(1-clamp(x),3);\nconst root=new THREE.Group();scene.add(root);\nconst geometries=[],materials=[];\nconst keepG=g=>(geometries.push(g),g),keepM=m=>(materials.push(m),m);\nconst typeColor=new THREE.Color(color),accentColor=new THREE.Color(accent);\nconst lightType=typeColor.r*.2126+typeColor.g*.7152+typeColor.b*.0722>.28;\nconst petalPalette=['#ffd4c0','#ef917e','#f8b7a3','#ffe8d4','#ce6972'].map(c=>new THREE.Color(c));\nconst gold=new THREE.Color('#dcc08a');\nconst label=createText(text,{fontSize,overflowWrap:'break-word',maxWidth:width*.75,textAlign:'center',lineHeight:1.25,color,fillOpacity:0,outlineWidth:'1.8%',outlineColor:lightType?'#4b3046':'#fff1e5',outlineOpacity:0,textStart:0});\nroot.add(label);label.renderOrder=10;\nconst textMaterials=Array.isArray(label.material)?label.material:[label.material];\nfor(const material of textMaterials){material.depthTest=false;material.depthWrite=false;}\nconst petalG=keepG(new THREE.PlaneGeometry(1,1,10,10));\nconst positions=petalG.attributes.position;\nfor(let i=0;i<positions.count;i++){\n const x=positions.getX(i),y=positions.getY(i);\n positions.setZ(i,.19*Math.abs(x)+.12*Math.pow(y+.3,2)-.035);\n}\npositions.needsUpdate=true;petalG.computeVertexNormals();\nconst vertex=`varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`;\nconst petalFrag=`precision highp float;\nvarying vec2 vUv;uniform vec3 uColor,uAccent;uniform float uAlpha,uSide;\nvoid main(){\n vec2 p=vUv*2.-1.;float y=p.y;\n float q=clamp((y+.96)/1.86,0.,1.);\n float width=.85*pow(max(0.,sin(q*3.14159265)),.70)*(0.74+.26*q);\n float edge=1.-smoothstep(width-.035,width+.014,abs(p.x));\n float tip=smoothstep(-1.,-.92,y)*(1.-smoothstep(.85,.96,y));\n float notch=smoothstep(.065,.13,length(vec2(p.x*1.2,(y-.88)*1.4)));\n float crease=smoothstep(-.025,.04,p.x+.04*y);\n vec3 c=mix(uColor*.80,mix(uColor,vec3(1.,.94,.83),.27),crease);\n c=mix(c,uAccent,.10*(1.-q));\n c+=vec3(.11,.07,.04)*pow(max(0.,1.-abs(p.x)),14.);\n float vein=(1.-smoothstep(.007,.018,abs(p.x+.04*y)))*.15;\n c+=vec3(vein);float a=edge*tip*notch*uAlpha;\n if(a<.002)discard;gl_FragColor=vec4(c,a);\n #include <colorspace_fragment>\n}`;\nconst petals=[];\nfor(let i=0;i<36;i++){\n const m=keepM(new THREE.ShaderMaterial({transparent:true,side:THREE.DoubleSide,depthTest:false,depthWrite:false,uniforms:{uColor:{value:petalPalette[i%petalPalette.length]},uAccent:{value:accentColor},uAlpha:{value:0},uSide:{value:0}},vertexShader:vertex,fragmentShader:petalFrag}));\n const mesh=new THREE.Mesh(petalG,m);mesh.renderOrder=i%4===0?4:2;root.add(mesh);\n const a=i/36*Math.PI*2+(random()-.5)*.18;\n petals.push({mesh,m,a,phase:random()*6.283,spread:.81+random()*.21,size:S*(.018+random()*.035)*(i%9===0?1.65:1),delay:random()*.11,rotation:random()*6.283,turn:(random()-.5)*1.6,depth:random()*30-15,round:random()});\n}\n// Three open, tilted hairline ellipses are drawn on once, then quietly suspended.\nconst orbits=[];\nfor(let j=0;j<3;j++){\n const pts=[];for(let i=0;i<=160;i++){const a=(-.08+i/160*1.79)*Math.PI;pts.push(new THREE.Vector3(Math.cos(a),Math.sin(a),0));}\n const g=keepG(new THREE.BufferGeometry().setFromPoints(pts));\n const m=keepM(new THREE.LineBasicMaterial({color:j===1?accentColor:gold,transparent:true,opacity:0,depthTest:false,depthWrite:false}));\n const line=new THREE.Line(g,m);line.renderOrder=-2;root.add(line);orbits.push({g,m,line,j});\n}\n// A translucent breathing veil preserves readability while keeping the canvas alpha.\nconst veilG=keepG(new THREE.PlaneGeometry(1,1));\nconst veilM=keepM(new THREE.ShaderMaterial({transparent:true,depthTest:false,depthWrite:false,uniforms:{uColor:{value:new THREE.Color(lightType?'#2d2439':'#fff3e5')},uAlpha:{value:0}},vertexShader:vertex,fragmentShader:`precision highp float;varying vec2 vUv;uniform vec3 uColor;uniform float uAlpha;void main(){vec2 p=(vUv-.5)*2.;float r=length(p*vec2(.88,1.));float a=pow(max(0.,1.-r*r),2.)*uAlpha;if(a<.002)discard;gl_FragColor=vec4(uColor,a);\n #include <colorspace_fragment>\n}`}));\nconst veil=new THREE.Mesh(veilG,veilM);veil.renderOrder=5;root.add(veil);\nconst dustG=keepG(new THREE.CircleGeometry(1,7)),dust=[];\nfor(let i=0;i<64;i++){\n const m=keepM(new THREE.MeshBasicMaterial({color:i%8===0?accentColor:gold,transparent:true,opacity:0,depthTest:false,depthWrite:false}));\n const mesh=new THREE.Mesh(dustG,m);mesh.renderOrder=3;root.add(mesh);\n dust.push({mesh,m,a:random()*6.283,r:.75+random()*.39,phase:random()*6.283,size:S*(.0009+random()*.0023),delay:random()*.21});\n}\nconst diamondG=keepG(new THREE.PlaneGeometry(1,1));\nconst diamondM=keepM(new THREE.MeshBasicMaterial({color:gold,transparent:true,opacity:0,depthTest:false,depthWrite:false}));\nconst diamond=new THREE.Mesh(diamondG,diamondM);diamond.renderOrder=6;root.add(diamond);\nreturn {\n update(t){\n  const p=clamp(t/D),out=smooth((p-.79)/.21),fade=smooth(p/.15)*(1-out);\n  const bounds=label.textRenderInfo?.blockBounds;\n  const bw=bounds?Math.max(1,bounds[2]-bounds[0]):Math.max(fontSize,Array.from(text).length*fontSize*.65);\n  const bh=bounds?Math.max(1,bounds[3]-bounds[1]):fontSize*1.25;\n  const fit=Math.min(1,width*.75/bw,height*.45/bh),textH=bh*fit;\n  const rx=width*.425,ry=Math.min(height*.41,Math.max(textH*.81+S*.08,S*.255));\n  const titleIn=ease((p-.12)/.24),titleFade=smooth((p-.13)/.17)*(1-smooth((p-.79)/.17));\n  label.scale.setScalar(fit*(.965+.035*titleIn));\n  label.position.set(0,-S*.022*(1-titleIn)+out*S*.018,45);\n  label.rotation.set(0,0,0);label.fillOpacity=titleFade;label.outlineOpacity=titleFade*.48;\n  veil.scale.set(width*.89,Math.max(textH*1.95,S*.28),1);\n  veil.position.set(0,0,35);veilM.uniforms.uAlpha.value=titleFade*(lightType?.42:.36);\n  for(const f of petals){\n   const arrive=ease((p-f.delay)/.32),a=f.a+p*.34+(1-arrive)*-.40;\n   const scatter=1+(1-arrive)*.60+out*.30;\n   const x=Math.cos(a)*rx*f.spread*scatter;\n   const y=Math.sin(a)*ry*f.spread*scatter;\n   f.mesh.position.set(x+Math.sin(p*4+f.phase)*S*.006,y+Math.sin(p*3.2+f.phase)*S*.007+out*S*.065,f.depth);\n   f.mesh.rotation.set(Math.sin(p*3+f.phase)*.40,Math.cos(p*3.3+f.phase)*.58,f.rotation+f.turn*p+(1-arrive)*.70);\n   const size=f.size*(.7+.3*arrive);\n   f.mesh.scale.set(size*(.8+f.round*.22),size*1.36,size);\n   f.m.uniforms.uAlpha.value=smooth((p-f.delay)/.16)*(1-out)*(.66+f.round*.28);\n  }\n  for(const {g,m,line,j} of orbits){\n   line.scale.set(rx*(.93+j*.053),ry*(.89+j*.062),1);\n   line.position.set(0,0,-22-j);line.rotation.z=(j-1)*.032+Math.sin(p*2)*.016;\n   g.setDrawRange(0,Math.floor(161*ease((p-j*.035)/.36)));\n   m.opacity=fade*(j===1?.22:.36)*(1-j*.14);\n  }\n  for(const f of dust){\n   const arrive=ease((p-f.delay)/.30),a=f.a+p*.20;\n   f.mesh.position.set(Math.cos(a)*rx*f.r*(1+(1-arrive)*.3),Math.sin(a)*ry*f.r+Math.sin(p*3+f.phase)*S*.008,12);\n   const pulse=.65+.35*Math.pow(Math.sin(p*7+f.phase),2);\n   f.mesh.scale.setScalar(f.size*(.8+.2*arrive));\n   f.m.opacity=smooth((p-f.delay)/.16)*(1-out)*pulse*.80;\n  }\n  diamond.position.set(0,-Math.max(textH*.60+S*.035,S*.12),40);\n  diamond.rotation.z=Math.PI*.25;\n  diamond.scale.setScalar(S*.008*ease((p-.22)/.20));\n  diamondM.opacity=titleFade*.70;\n  root.visible=p>0&&p<1;\n },\n dispose(){scene.remove(root);for(const g of geometries)g.dispose();for(const m of materials)m.dispose();}\n};\n",
