    "source": "// 星を編む / CONSTELLATION — original motion by こはく\n// UNFOLD: Three.js r180 + Troika. The entire animation is a function of t.\nconst {THREE,scene,createText,text,width:W,height:H,fontSize,color,accent,duration:D,random}=api;\nconst clamp=x=>Math.max(0,Math.min(1,x));\nconst smooth=x=>{x=clamp(x);return x*x*(3-2*x)};\nconst root=new THREE.Group();scene.add(root);\nconst size=Math.min(W,H),objects=[];\nconst label=createText(text,{fontSize:Math.min(fontSize,H*.15),overflowWrap:'break-word',maxWidth:W*.76,textAlign:'center',lineHeight:1.27,letterSpacing:.06,color,outlineColor:'#091520',outlineWidth:'1%',outlineOpacity:.4});\nlabel.position.z=20;label.renderOrder=10;\nconst labelGlow=createText(text,{fontSize:Math.min(fontSize,H*.15),overflowWrap:'break-word',maxWidth:W*.76,textAlign:'center',lineHeight:1.27,letterSpacing:.06,color:accent,colorRanges:null,outlineColor:accent,outlineWidth:'2%',outlineOpacity:.15});\nlabelGlow.position.z=19;labelGlow.renderOrder=9;\nconst N=260,positions=new Float32Array(N*3),weights=new Float32Array(N),data=[];\nfor(let i=0;i<N;i++){const angle=random()*Math.PI*2,rad=.5+random()*.5;data.push({angle,rad,x:(random()-.5)*W*1.25,y:(random()-.5)*H*1.25,phase:random()*6.283,s:random(),z:random()*8});weights[i]=1.2+random()*3.1;}\nconst geom=new THREE.BufferGeometry();geom.setAttribute('position',new THREE.BufferAttribute(positions,3));geom.setAttribute('weight',new THREE.BufferAttribute(weights,1));\nconst mat=new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,uniforms:{tint:{value:new THREE.Color(accent)},alpha:{value:0}},vertexShader:'attribute float weight;varying float vWeight;void main(){vWeight=weight;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);gl_PointSize=weight*4.;}',fragmentShader:`uniform vec3 tint;uniform float alpha;varying float vWeight;void main(){vec2 q=gl_PointCoord-.5;float r=length(q);float soft=exp(-r*r*24.);float core=exp(-r*r*220.);gl_FragColor=vec4(mix(tint,vec3(1.),core*.85),alpha*(soft*.32+core*.8));\n #include <colorspace_fragment>\n}`});\nconst particles=new THREE.Points(geom,mat);root.add(particles);objects.push(geom,mat);\nconst rings=[];\nfor(let j=0;j<3;j++){const g=new THREE.BufferGeometry(),p=new Float32Array(97*3);for(let i=0;i<=96;i++){const a=i/96*Math.PI*2;p[i*3]=Math.cos(a)*W*(.31+j*.02);p[i*3+1]=Math.sin(a)*H*(.29+j*.032);p[i*3+2]=-10;}g.setAttribute('position',new THREE.BufferAttribute(p,3));const m=new THREE.LineBasicMaterial({color:j===1?color:accent,transparent:true,opacity:0,depthWrite:false});const line=new THREE.Line(g,m);root.add(line);rings.push(line);objects.push(g,m);}\nconst starGeometry=new THREE.BufferGeometry();starGeometry.setAttribute('position',new THREE.Float32BufferAttribute([-7,0,0,7,0,0,0,-7,0,0,7,0,-2,-2,0,2,2,0,-2,2,0,2,-2,0],3));\nconst starMaterial=new THREE.LineBasicMaterial({color:accent,transparent:true,opacity:0,depthWrite:false});const star=new THREE.LineSegments(starGeometry,starMaterial);star.position.y=H*.285;root.add(star);objects.push(starGeometry,starMaterial);\nconst threadGeo=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-W*.07,-H*.255,0),new THREE.Vector3(W*.07,-H*.255,0)]);\nconst threadMat=new THREE.LineBasicMaterial({color:accent,transparent:true,opacity:0,depthWrite:false});root.add(new THREE.Line(threadGeo,threadMat));objects.push(threadGeo,threadMat);\nfunction fit(mesh){const b=mesh.textRenderInfo?.blockBounds;return b?Math.min(1,W*.78/Math.max(1,b[2]-b[0]),H*.43/Math.max(1,b[3]-b[1])):1;}\nreturn {update(t){\n const q=clamp(t/Math.max(.001,D)),enter=smooth(q/.22),exit=smooth((q-.75)/.25),a=enter*(1-exit),settle=1-Math.pow(1-enter,3);\n root.visible=a>0;label.visible=a>0;labelGlow.visible=a>0;\n const scale=fit(label);label.scale.setScalar(scale*(.96+.04*settle));labelGlow.scale.copy(label.scale);\n label.position.y=(1-settle)*-H*.055+exit*H*.025;labelGlow.position.y=label.position.y;\n label.fillOpacity=a;label.outlineOpacity=a*.4;labelGlow.fillOpacity=a*.12;labelGlow.outlineOpacity=a*.11;\n for(let i=0;i<N;i++){const d=data[i],rot=q*.3+d.phase*.035,angle=d.angle+rot;const hx=Math.cos(angle)*W*(.30+.15*d.rad),hy=Math.sin(angle)*H*(.24+.19*d.rad);const ease=smooth((q-d.s*.075)/.24);positions[i*3]=d.x*(1-ease)+hx*ease+Math.cos(d.angle)*exit*W*.16;positions[i*3+1]=d.y*(1-ease)+hy*ease+Math.sin(q*6+d.phase)*H*.012+Math.sin(d.angle)*exit*H*.18;positions[i*3+2]=d.z;}\n geom.attributes.position.needsUpdate=true;mat.uniforms.alpha.value=a*(.75+Math.sin(q*6.283)*.1);\n rings.forEach((r,i)=>{r.rotation.z=(i-1)*.11+q*(i%2?-.055:.06);r.scale.setScalar(.75+.25*settle+exit*.12);r.material.opacity=a*(i===1?.08:.14);r.geometry.setDrawRange(0,Math.round(97*smooth(q/.29)*(1-exit*.35)));});\n star.rotation.z=q*.2;star.scale.setScalar(.6+.4*settle);starMaterial.opacity=a*.8;threadMat.opacity=a*.5;\n },dispose(){objects.forEach(o=>o.dispose());root.removeFromParent();label.dispose();labelGlow.dispose();}};\n",
