    "key": "sample:collection:01_nunome",
    "name": "織り写真",
    "kind": "image",
    "source": "// 織り写真｜画像JavaScript関数本体。立体化なし専用。\nconst {createImagePlane,size}=api;\nconst DENSITY=16; // 模様の密度：4〜40\nconst DEPTH=0.85; // 変位・ハイライトの強さ：0〜1（0でも織り陰影は残る）\nconst SPEED=1; // 持続中の動き：0〜2\nconst clamp=(v,a,b)=>Math.max(a,Math.min(b,v));\nconst plane=createImagePlane(), material=plane.material;\nObject.assign(material.uniforms,{\n fxAmount:{value:0},fxTime:{value:0},fxDensity:{value:clamp(DENSITY,4,40)},\n fxDepth:{value:clamp(DEPTH,0,1)},fxSpeed:{value:clamp(SPEED,0,2)},\n fxAspect:{value:Math.max(.01,size.width/Math.max(.001,size.height))}\n});\nmaterial.transparent=true; material.depthWrite=false;\nmaterial.fragmentShader=`\nuniform sampler2D a,b;\nuniform float mixImage,fxAmount,fxTime,fxDensity,fxDepth,fxSpeed,fxAspect;\nvarying vec2 vUv;\nvec4 sampleImage(vec2 uv){return mix(texture2D(a,uv),texture2D(b,uv),mixImage);}\nvoid main(){\n vec4 original=sampleImage(vUv);\n float s=fxAmount,t=fxTime*fxSpeed;\n vec3 result;\n\n vec2 q=vUv*vec2(fxAspect,1.0)*fxDensity;\n vec2 cell=floor(q), f=fract(q);\n float parity=mod(cell.x+cell.y,2.);\n float bend=sin(q.y*.7+t*1.7)*.10+sin(q.x*.45-t)*.06;\n float ridge=sin((parity<.5?f.x:f.y)*3.14159265);\n vec2 shift=vec2(sin(q.y*1.4+t),cos(q.x*1.1-t*.8))*.035*fxDepth*s;\n vec4 tex=sampleImage(clamp(vUv+shift,vec2(.001),vec2(.999)));\n vec3 safe=mix(original.rgb,tex.rgb,tex.a);\n float strand=(parity<.5?f.x:f.y);\n float edge=smoothstep(.015,.11,strand)*(1.-smoothstep(.89,.985,strand));\n float fibers=.94+.06*sin((parity<.5?q.x:q.y)*80.+bend*9.);\n float flutter=.84+.16*sin(q.x*.6+q.y*.8-t*2.);\n float shade=mix(.12,(.45+.65*ridge)*fibers*flutter,edge);\n result=safe*shade+vec3(.10,.075,.04)*pow(ridge,12.)*fxDepth;\n\n gl_FragColor=vec4(mix(original.rgb,result,s),original.a);\n #include <colorspace_fragment>\n}\n`;\nmaterial.needsUpdate=true;\nconst smooth=x=>{x=clamp(x,0,1);return x*x*(3-2*x);};\nreturn {\n physicsTime:()=>0,\n update(frame){\n  const p=clamp(Number.isFinite(frame.progress)?frame.progress:0,0,1);\n  const amount=clamp(Number.isFinite(frame.amount)?frame.amount:0,0,1);\n  material.uniforms.fxAmount.value=amount*smooth(p/.16)*smooth((1-p)/.18);\n  material.uniforms.fxTime.value=Number.isFinite(frame.clipTime)?frame.clipTime:0;\n }\n};\n",
